        if (predicate is null) throw new InvalidOperationException("ERROR: no condition specified for .Where()");
        if (value is not Data data) return value;
        Dictionary<string, object?> dollars = new(StringComparer.Ordinal);
        if (Current is not null)
            foreach (var entry in Current.Values)
                if (entry.Key.StartsWith('$')) dollars[entry.Key] = Materialize(entry.Value, Current);
        List<Data> matches = new();
        foreach (Data item in data.Items ?? new List<Data> { data })
        {
            foreach (var entry in dollars) item.Values[entry.Key] = entry.Value;
            object? selected = predicate(new EvaluationContext(this, item));
            if (selected is object?[] sequence) selected = sequence.Length == 0 ? null : sequence[0];
            selected = Intermediate(selected);
            bool keep = Condition(selected) && !(data.Items is not null && selected is string text && (falsy?.Test(text) ?? false));
            // The reference removes injected bindings only from accepted list items.
            if (keep || data.Items is null)
                foreach (string name in dollars.Keys) item.Values.Remove(name);
            if (keep)
            {
                if (data.Items is not null)
                    foreach (string name in new List<string>(item.Values.Keys))
                        if (name.StartsWith('$')) item.Values.Remove(name);
                matches.Add(item);
            }
        }
        if (matches.Count == 0) return MissingValue("list");
        if (matches.Count == 1) return CloneGroupData(matches[0], Current);
        Data result = new(new(StringComparer.Ordinal), Current) { Items = new() };
        foreach (Data item in matches) result.Items.Add(CloneGroupData(item, result));
        return result;
    }
    // callMethod GroupBy: defer the key, preserve group members, and sort JS property keys.
    internal object? GroupBy(object? value, Func<EvaluationContext, object?> selector, string keyText, object?[] arguments, bool contextProbe = false)
    {
        value = Intermediate(value);
        if (value is null or Missing) return value;
        if (contextProbe && value is string) return value;
        if (arguments.Length == 1 && !Regex.IsMatch(keyText, @"^[a-zA-Z_][a-zA-Z0-9_]*$"))
            throw new InvalidOperationException("An alias (third parameter) must be provided for the GroupBy name.");
        if (value is not Data data)
        {
            // Resource strings are resolved later by context evaluation, as in the reference.
            if (value is string path && (path.StartsWith('/') || path.StartsWith("http", StringComparison.Ordinal))) return value;
            throw new InvalidOperationException("Invalid data for GroupBy.");
        }
        if (arguments.Length < 1) throw new InvalidOperationException("Invalid arguments for GroupBy.");
        Dictionary<string, List<Data>> groups = CollectGroups(data, selector);
        string groupingName = arguments.Length == 2 ? Builtins.JsString(arguments[1]) : keyText;
        string membersName = Builtins.JsString(arguments[0]);
        List<string> keys = new(groups.Keys);
        keys.Sort(StringComparer.Ordinal);
        Data result = new(new(StringComparer.Ordinal), Current);
        if (keys.Count != 1) result.Items = new();
        foreach (string key in keys)
        {
            Data group = keys.Count == 1 ? result : new(new(StringComparer.Ordinal), result);
            if (groupingName != "__proto__") group.Values[groupingName] = key;
            List<Data> members = groups[key];
            group.Values[membersName] = members.Count == 1 ? CloneGroupData(members[0], group)
                : CloneGroupData(new Data(new(StringComparer.Ordinal), null) { Items = members }, group);
            result.Items?.Add(group);
        }
        return result;
    }
    // OrderBy and GroupBy use the same deferred-key grouping algorithm in the reference.
    internal object? OrderBy(object? value, Func<EvaluationContext, object?> selector, string keyText, object?[] arguments, bool contextProbe = false)
    {
        value = Intermediate(value);
        if (value is null or Missing) return value;
        string mode = "A";
        if (arguments.Length == 1)
        {
            if (Intermediate(arguments[0]) is not string direction)
                throw new InvalidOperationException("OrderBy direction must be a string.");
            static string ReplaceFirst(string text, string find, string replacement)
            {
                int index = text.IndexOf(find, StringComparison.Ordinal);
                return index < 0 ? text : text[..index] + replacement + text[(index + find.Length)..];
            }
            mode = ReplaceFirst(ReplaceFirst(NodeCasing.Convert(direction, true), "ASC", "A"), "DESC", "D");
        }
        if (contextProbe && value is string) return value;
        if (value is not Data data)
        {
            if (value is string path && (path.StartsWith('/') || path.StartsWith("http", StringComparison.Ordinal))) return value;
            throw new InvalidOperationException("Invalid data for OrderBy.");
        }
        if (keyText.Length == 0 || arguments.Length > 1 || mode is not ("A" or "D" or "U"))
            throw new InvalidOperationException("Invalid arguments for OrderBy.");
        Dictionary<string, List<Data>> groups = CollectGroups(data, selector);
        List<string> keys = new(groups.Keys);
        keys.Sort(StringComparer.Ordinal);
        if (mode == "D") keys.Reverse();
        List<Data> ordered = new();
        foreach (string key in keys)
        {
            if (mode == "U") ordered.Add(groups[key][0]);
            else ordered.AddRange(groups[key]);
        }
        if (ordered.Count == 1) return CloneGroupData(ordered[0], Current);
        Data result = new(new(StringComparer.Ordinal), Current) { Items = new() };
        foreach (Data row in ordered) result.Items.Add(CloneGroupData(row, result));
        return result;
    }
    private Dictionary<string, List<Data>> CollectGroups(Data data, Func<EvaluationContext, object?> selector)
    {
        Dictionary<string, object?> dollars = new(StringComparer.Ordinal);
        if (Current is not null)
            foreach (var entry in Current.Values)
                if (entry.Key.StartsWith('$')) dollars[entry.Key] = Materialize(entry.Value, Current);
        Dictionary<string, List<Data>> groups = new(StringComparer.Ordinal);
        foreach (Data item in data.Items ?? new List<Data> { data })
        {
            foreach (var entry in dollars) item.Values[entry.Key] = entry.Value;
            string key;
            try
            {
                EvaluationContext child = new(this, item);
                object? selected = selector(child);
                key = Builtins.JsString(Intermediate(selected));
            }
            finally
            {
                // Legacy deletes these keys even when they replaced existing item properties.
                foreach (string name in dollars.Keys) item.Values.Remove(name);
            }
            // The reference uses {}, not a prototype-free map. Inherited function names
            // contribute an empty record; assigning __proto__ creates no enumerable key.
            if (key == "__proto__") continue;
            if (!groups.TryGetValue(key, out List<Data>? members))
            {
                groups[key] = members = new();
                if (key is "constructor" or "toString" or "toLocaleString" or "valueOf" or
                    "hasOwnProperty" or "isPrototypeOf" or "propertyIsEnumerable" or
                    "__defineGetter__" or "__defineSetter__" or "__lookupGetter__" or "__lookupSetter__")
                    members.Add(new Data(new(StringComparer.Ordinal), null));
            }
            members.Add(item);
        }
        return groups;
    }
    // TemplateData clones grouped records; rebuild parent links instead of retaining source parents.
    private static Data CloneGroupData(Data source, Data? parent)
    {
        Data copy = new(new(StringComparer.Ordinal), parent);
        if (source.Items is not null)
        {
            copy.Items = new();
            foreach (Data item in source.Items) copy.Items.Add(CloneGroupData(item, copy));
        }
        else
            foreach (var entry in source.Values)
            {
                object? value = Materialize(entry.Value, source);
                copy.Values[entry.Key] = value is Data child ? CloneGroupData(child, copy) : value;
            }
        return copy;
    }
    internal static object? JoinValues(object? value, params object?[] arguments)
    {
        if (arguments.Length > 2) throw new NotImplementedException("Join with more than two arguments is not implemented.");
        value = Intermediate(value);
        List<object?>? items = value is Arguments argumentsList ? argumentsList.Items : null;
        if (value is Data data)
        {
            if (data.Items is null) throw new NotImplementedException("Join requires a scalar list.");
            items = new();
            foreach (Data item in data.Items)
            {
                if (!item.Values.TryGetValue("_", out object? scalar) || !Condition(scalar))
                    throw new NotImplementedException("Join requires a scalar list.");
                items.Add(scalar);
            }
        }
        if (items is null) return value;
        List<string> kept = new List<string>();
        foreach (object? item in items) if (Condition(item)) kept.Add(Compose(item) ?? "");
        string separator = arguments.Length > 0 ? Compose(arguments[0]) ?? "" : ", ";
        string lastSeparator = arguments.Length > 1 ? Compose(arguments[1]) ?? "" : separator;
        if (kept.Count < 2) return string.Join("", kept);
        return string.Join(separator, kept.GetRange(0, kept.Count - 1)) + lastSeparator + kept[^1];
    }
    internal TResult Scope<TResult>(Dictionary<string, Func<EvaluationContext, object?>> definitions, Func<EvaluationContext, TResult> body, Dictionary<string, Func<EvaluationContext, EvaluationContext>>? includes = null)
    {
        EvaluationContext child = new EvaluationContext(this, Current);
        foreach (KeyValuePair<string, Func<EvaluationContext, object?>> entry in definitions) child.Locals[entry.Key] = entry.Value;
        if (includes is not null) foreach (var entry in includes) child.imports[entry.Key] = entry.Value;
        return body(child);
    }
    internal object? Named(string name)
    {
        if (!Locals.TryGetValue(name, out Func<EvaluationContext, object?>? method) && !Shared.TryGetValue(name, out method))
            throw new InvalidOperationException("Subtemplate #" + name + " not found.");
        if (++recursion.Value > 20) { recursion.Value--; throw new InvalidOperationException("Subtemplate recursion exceeds 20 levels."); }
        try { return method(this); }
        finally { recursion.Value--; }
    }
    internal static object? Invoke(object? value, Func<object?, object?> method)
    {
        if (value is not Multiline multiline) return method(value);
        object? result = Intermediate(method(multiline.Text));
        return result is string text && text.Contains('\n') ? new Multiline(text, multiline.Styles) : result;
    }
    internal static object? Intermediate(object? value)
    {
        if (value is TemplateContent content)
            return content.Fragments.Length == 1 ? Intermediate(content.Fragments[0]) : Compose(content);
        if (value is RenderedList or Multiline) return Compose(value);
        return value is object?[] sequence ? sequence.Length == 1 ? Intermediate(sequence[0]) : Compose(value) : value;
    }
    internal static bool Condition(object? value)
    {
        value = Intermediate(value);
        return value switch { null or Missing => false, string text => text.Length > 0,
            bool flag => flag, double number => number != 0 && !double.IsNaN(number), _ => true };
    }
    internal static bool Compare(object? left, string operation, object? right)
    {
        left = Intermediate(left); right = Intermediate(right);
        bool lm = left is null or Missing, rm = right is null or Missing;
        // Preserve the legacy missing-value comparison behavior, including its unusual cases.
        if (lm) return rm || operation == "!=";
        if (rm) return operation == "!=";
        string a = left is TemplateDate ? Builtins.JsString(left) : Scalar(left!), b = right is TemplateDate ? Builtins.JsString(right) : Scalar(right!);
        int? comparison = Builtins.CompareStrings(a, b);
        if (comparison is null) return operation == "!=";
        int order = comparison.Value;
        return operation switch { "=" or "==" => order == 0, "!=" => order != 0, ">" => order > 0,
            "<" => order < 0, ">=" => order >= 0, "<=" => order <= 0, _ => throw new InvalidOperationException(operation) };
    }
    internal static double ParseInteger(string text)
    {
        Match match = Regex.Match(text.TrimStart(Builtins.Whitespace.ToCharArray()), @"^[+-]?[0-9]+");
        return match.Success ? double.Parse(match.Value, CultureInfo.InvariantCulture) : double.NaN;
    }
    internal static string Scalar(object value) => value switch
    {
        string text => text, TemplateDate date => date.Render(), bool flag => flag ? "true" : "false",
        double number => NumberText(number),
        _ => throw new NotImplementedException("Non-scalar composition requires list/data formatting, which is not implemented yet.")
    };
    private static string NumberText(double number)
    {
        string text = number.ToString("R", CultureInfo.InvariantCulture);
        if (number == 0) return "0";
        int e = text.IndexOf('E');
        if (e < 0) return text;
        int exponent = int.Parse(text[(e + 1)..], CultureInfo.InvariantCulture);
        if (exponent >= -6 && exponent < 21) return number.ToString("0.####################", CultureInfo.InvariantCulture);
        return text[..e] + "e" + (exponent >= 0 ? "+" : "-") + Math.Abs(exponent).ToString(CultureInfo.InvariantCulture);
    }
    // Retain the fragment hierarchy until rendering; a missing value removes its entire line.
    internal static string? Compose(object? value, List<string>? bulletKeys = null, bool exposeMissing = false)
    {
        List<string> lines = new List<string> { "" };
        bool skipping = false;
        void VisitSequence(IReadOnlyList<object?> fragments, string? indent)
        {
            for (int i = 0; i < fragments.Count; i++)
            {
                if (fragments[i] is Bullet bullet)
                {
                    Visit(bullet.Marker);
                    var rest = new List<object?>();
                    for (i++; i < fragments.Count; i++) rest.Add(fragments[i]);
                    VisitSequence(rest, bullet.Marker);
                    return;
                }
                Visit(fragments[i], indent);
            }
        }
        void Visit(object? item, string? indent = null)
        {
            // Traverse fragments directly: ToString would lose missing-line and indentation behavior.
            // Legacy changes a bullet indent to plain indentation only when entering
            // an array, not between every scalar and list fragment in that array.
            if (item is TemplateContent or object?[])
            {
                string prefix = Regex.Match(lines[^1], @"^[ \t]*(?:\x01\{\.\})?").Value;
                if (indent?.Contains("\x01{.}") == true && !prefix.Contains("\x01{.}") && prefix.Length > 0)
                    indent = prefix;
            }
            if (item is TemplateContent templateContent) { VisitSequence(templateContent.Fragments, indent); return; }
            if (item is object?[] sequence) { VisitSequence(sequence, indent); return; }
            if (item is Bullet bullet) { Visit(bullet.Marker); return; }
            if (item is Data data)
            {
                if (data.Items is not null)
                {
                    List<string> scalars = new();
                    bool scalarList = true;
                    foreach (Data child in data.Items)
                    {
                        if (!child.Values.TryGetValue("_", out object? scalar) || !Condition(scalar)) { scalarList = false; break; }
                        scalars.Add(Scalar(scalar!));
                    }
                    // Raw object-data lists retain their layout. A dictionary contributes
                    // no text unless its scalar '_' value can be interpolated.
                    item = scalarList ? string.Join(", ", scalars) : new RenderedList(new List<object?>(data.Items));
                }
                else if (data.Values.TryGetValue("_", out object? scalar) && Condition(scalar)) item = scalar;
                else return;
            }
            if (item is Arguments arguments) item = new RenderedList(arguments.Items);
            if (item is RenderedList rendered)
            {
                if (rendered.Items.Count == 0) return;
                string preview = Compose(rendered.Items[0]) ?? "";
                bool startsWithBullet = Regex.IsMatch(preview, @"^\s*\x01\{\.\}");
                if (indent?.Contains("\x01{.}") == true)
                {
                    bool unfinished = Regex.IsMatch(lines[^1], @"^[ \t]*\x01\{\.\}[ \t]*$");
                    string nextBullet = Regex.Replace(indent, @"([ \t]*\x01\{\.\})", (rendered.DefaultIndent ?? "   ") + "$1");
                    for (int i = 0; i < rendered.Items.Count; i++)
                    {
                        object? child = rendered.Items[i];
                        string marker = unfinished ? indent : nextBullet;
                        if (i == 0 && unfinished) Visit(child, indent);
                        else
                        {
                            string firstMarker = startsWithBullet ? FirstBullet(child) : marker;
                            if (i > 0 && !indent.Contains('\n') && !firstMarker.Contains('\n')) Visit("\n");
                            if (!startsWithBullet) VisitSequence(new object?[] { new Bullet(marker, rendered.DefaultIndent), child }, indent);
                            else Visit(child, indent);
                        }
                    }
                    return;
                }
                bool emptyLine = lines[^1] == "";
                string lastIndent = Regex.Match(lines[^1], @"^[ \t]*").Value;
                string? nextIndent = (rendered.DefaultIndent ?? "   ") + (indent ?? lastIndent);
                if (Regex.Match(preview, @"^[ \t]*").Length > lastIndent.Length) nextIndent = null;
                bool incomplete = lines[^1] == indent;
                if (incomplete) nextIndent = indent;
                else if (lastIndent == lines[^1]) { nextIndent = lastIndent; incomplete = true; }
                bool first = true;
                foreach (object? child in rendered.Items)
                {
                    object? content = child;
                    if (preview.StartsWith('\n')) nextIndent = indent;
                    else if (!(incomplete && first) && (!emptyLine || !first))
                    {
                        Visit("\n" + (startsWithBullet ? "" : nextIndent));
                        if (!startsWithBullet && !string.IsNullOrEmpty(nextIndent) && content is string text)
                            content = text.Replace("\n", "\n" + nextIndent);
                    }
                    Visit(content, nextIndent);
                    first = false;
                }
                return;
            }
            if (item is Multiline multiline)
            {
                bool Has(string style)
                {
                    foreach (string candidate in multiline.Styles) if (candidate == style) return true;
                    return false;
                }
                bool allButFirst = Has("IndentAllButFirst"), padded = Has("Padded"), tabbed = Has("Tabbed");
                bool indented = Has("Indented"), trimmed = Has("Trimmed"), offset = Has("Offset");
                int width = 0;
                if (indented || allButFirst || tabbed)
                    width = 4 + (!tabbed && lines.Count > 1 ? Regex.Match(lines[^1], "^ *").Length : 0);
                var pieces = new List<string>(multiline.Text.Split('\n'));
                if (indented || allButFirst)
                    for (int i = 0; i < pieces.Count; i++) pieces[i] = pieces[i].Trim(Builtins.Whitespace.ToCharArray());
                if (padded)
                    while (pieces.Count > 1 && pieces[^1].Trim(Builtins.Whitespace.ToCharArray()).Length == 0)
                        pieces.RemoveAt(pieces.Count - 1);
                string padding = new string(' ', width);
                string joined = string.Join("\n" + padding, pieces);
                if (trimmed) joined = Regex.Replace(Regex.Replace(joined, " *\n", "\n"), "\n{3,}", "\n\n");
                item = (allButFirst ? "" : (offset ? "\n" : "") + padding) + joined + (padded ? "\n" : "");
            }
            if (item is Missing missing) item = exposeMissing
                    ? "***Missing value for " + missing.Key + " which would " + (string.IsNullOrEmpty(missing.Replacement) ? "cause the line to be skipped" : "be replaced by '" + missing.Replacement + "'") + "***"
                    : missing.Replacement;
            if (item is null) { lines[^1] = ""; skipping = true; return; }
            string[] parts = Scalar(item).Split('\n');
            for (int i = 0; i < parts.Length; i++)
            {
                if (i == 0 && skipping)
                {
                    if (parts.Length == 1) return;
                    skipping = false;
                }
                else
                {
                    Match bulletMatch = Regex.Match(parts[i], @"^[ \t]*\x01\{\.\}");
                    if (bulletMatch.Success)
                    {
                        if (bulletKeys is not null && !bulletKeys.Contains(bulletMatch.Value)) bulletKeys.Add(bulletMatch.Value);
                        if (lines[^1] != "") lines.Add("");
                    }
                    lines[^1] += parts[i];
                    if (i < parts.Length - 1) lines.Add("");
                }
            }
        }
        string FirstBullet(object? item)
        {
            if (item is TemplateContent content && content.Fragments.Length > 0) return FirstBullet(content.Fragments[0]);
            if (item is object?[] sequence && sequence.Length > 0) return FirstBullet(sequence[0]);
            return item is Bullet bullet ? bullet.Marker : "";
        }
        Visit(value);
        if (skipping)
        {
            if (lines.Count == 1) return null;
            lines.RemoveAt(lines.Count - 1);
        }
        return string.Join("\n", lines);
    }
}

